import re
t = open('template.html', encoding='utf8').read()
n = 0
def add(m):
    global n
    kk = m.group(1)
    if kk not in DK:
        raise SystemExit('missing: ' + kk)
    n += 1
    return m.group(0) + f',\n  dk:"{DK[kk]}"'
t2 = re.sub(r'kk:"([^"]+)",ru:"[^"]*",lat:[^\n]*\n  d:"[^"]*"', add, t)
open('template.html', 'w', encoding='utf8').write(t2)
print('patched', n, 'of', len(DK))
